  static long solve(int n,int[][] edges) {
List<List<int[]>> g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new ArrayList<>());for(int[] e:edges){g.get(e[0]).add(new int[]{e[1],e[2]});g.get(e[1]).add(new int[]{e[0],e[2]});}PriorityQueue<int[]> q=new PriorityQueue<>(Comparator.comparingInt(x->x[1]));q.add(new int[]{0,0});boolean[] used=new boolean[n];long total=0;int count=0;while(!q.isEmpty()){int[] edge=q.remove();int u=edge[0];if(used[u])continue;used[u]=true;count++;total+=edge[1];for(int[] next:g.get(u))if(!used[next[0]])q.add(next);emit("Choose the cheapest edge leaving the tree","vertex",u,"total",total,"visited",used);}return count==n?total:-1;
  }


